import csv
import sqlite3

def ingest(csv_path, database, fail_after=None):
    connection = sqlite3.connect(database)
    try:
        connection.execute("CREATE TABLE IF NOT EXISTS events (event_id TEXT PRIMARY KEY, amount INTEGER NOT NULL)")
        with connection:
            with open(csv_path, newline="") as stream:
                for index, row in enumerate(csv.DictReader(stream), 1):
                    connection.execute("INSERT INTO events VALUES (?, ?)", (row["event_id"], int(row["amount"])))
                    connection.commit()
                    if index == fail_after:
                        raise RuntimeError("injected interruption")
        return connection.execute("SELECT COUNT(*), COALESCE(SUM(amount), 0) FROM events").fetchone()
    finally:
        connection.close()

